mapper.update:
update pet_ai_conversation
title = #{title}, message_count = #{messageCount}, status = #{status}, store_id = #{storeId}, last_time = sysdate(), update_time = sysdate()
where conv_id = #{convId}

mapper.select:
select * from pet_ai_conversation
where user_id = #{userId}
order by last_time desc
limit #{limit}
